/**
 * Kitchen Locality Registry
 * Defines all target localities for the Modular Kitchen SEO cluster.
 * Each entry maps to a page at /modular-kitchen-{slug}.
 */

/** All page types that can be generated for a locality. Typed for autocomplete + safety. */
export type GeneratorType =
  | "hub"
  | "layout"
  | "material"
  | "budget"
  | "price"
  | "style"
  | "finish"
  | "renovation"
  | "repair"
  | "builder"
  | "guide";

export type KitchenLocalityEntry = {
  id: string;
  slug: string;
  name: string;
  city: "delhi" | "gurgaon" | "noida" | "ghaziabad" | "faridabad" | "chandigarh" | "mohali" | "panchkula";
  propertyType: string;
  affluence: "budget" | "mid" | "mid-high" | "high" | "ultra-high";
  premiumLevel: 1 | 2 | 3 | 4 | 5;
  landmarks: readonly string[];
  nearby: readonly string[];
  priority: number;
  status: "published" | "draft";
  rolloutGroup: number;         // 1=original batch, 2=next 25, 3+=future
  recommendedStyle: "modern" | "contemporary" | "minimalist" | "scandinavian";
  // New fields (milestone-210)
  priorityScore: number;           // 1–100, drives publish order and content emphasis
  tier: "tier1" | "tier2" | "tier3"; // tier1=90–100, tier2=70–89, tier3=50–69
  localityType: "villa" | "apartments" | "mixed"; // dominant property type
  averageProjectValue: "budget" | "mid" | "premium" | "luxury"; // expected spend level
  nearbyAreas?: readonly string[];  // optional display names for nearby areas (different from `nearby` which are SEO slugs)
  // Generator control (milestone-294) — optional, defaults provided at runtime
  searchDemandScore?: number;                      // 1–100 independent search opportunity estimate (update from GSC/Ahrefs)
  distanceScore?: number;                          // 0–100, higher = closer (used for nearby sorting)
  enabledGenerators?: readonly GeneratorType[];    // generators currently producing pages for this locality
  recommendedGenerators?: readonly GeneratorType[]; // generators recommended for next rollout batch
};

